(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.3)*20 + Math.cos(y*0.012-t*0.2)*15;
  const w1y = Math.cos(y*0.015-t*0.25)*20 + Math.sin(x*0.013+t*0.35)*15;
  const w2x = Math.sin((x+w1x)*0.025-t*0.5)*8 + Math.cos((y+w1y)*0.02+t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.025+t*0.45)*8 + Math.sin((x+w1x)*0.022-t*0.35)*6;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [];
  for (let i = 0; i < 8; i++) {
    const a = t*0.2 + i*Math.PI/4;
    src.push([
      cx + Math.cos(a)*(80+Math.sin(t*0.15+i*1.3)*60) + Math.sin(t*0.3+i*2)*30,
      cy + Math.sin(a)*(50+Math.cos(t*0.2+i*0.9)*40) + Math.cos(t*0.25+i*1.7)*25,
      0.04+Math.sin(i*0.7)*0.03, 1.5+Math.cos(i*0.5)*0.8
    ]);
  }
  let aS=0, iS=0, hS=0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    hS += Math.sin(d*f*1.3-t*sp*0.8+2.8);
  }
  const act=aS/8, inh=iS/8, harm=hS/8;
  const bg = (Math.sin(sx*0.03+sy*0.02+t*0.7)+Math.sin(sx*0.025-sy*0.035+t*0.9))/2
    + (Math.sin(sx*0.06+sy*0.05-t*1.2)+Math.sin(sx*0.05-sy*0.07+t*1.5))*0.3
    + (Math.sin(sx*0.12+sy*0.1+t*2.5)+Math.sin(sx*0.1-sy*0.14-t*2))*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.04-ang*3-t*1.5)+Math.sin(dist*0.035+ang*4-t*1.2))*0.35
    + (Math.sin(dist*0.06+ang*2-t*2)+Math.sin(dist*0.05-ang*5+t*1.8))*0.2;
  const vx=cx+Math.sin(t*0.4)*60, vy=cy+Math.cos(t*0.3)*40;
  const vd=Math.sqrt((sx-vx)**2+(sy-vy)**2), va=Math.atan2(sy-vy, sx-vx);
  const vortex = Math.sin(vd*0.08-va*2-t*3)*0.25*Math.exp(-vd*0.005);
  const reaction = Math.tanh((act-inh*0.65+harm*0.2+bg*0.25+spiral+vortex)*2.0);
  const diffusion = Math.tanh((act*0.5+inh*0.3-harm*0.4+bg*0.4-spiral*0.3)*1.5);
  const rd = Math.tanh((reaction*0.6+diffusion*0.4)*2.5);
  const cell = Math.tanh((Math.sin(sx*0.13)*Math.sin(sy*0.13)+Math.sin((sx+sy)*0.09+t)*0.4)*1.3)*0.25;
  const detail = Math.sin(sx*0.25+t*1.5)*Math.sin(sy*0.25-t*1.2)*0.08;
  const v = (rd*0.7+cell*0.2+detail*0.1)*0.5+0.5;
  const pal = [[5,12,45],[12,45,85],[18,85,120],[25,140,135],[55,175,130],[160,195,85],[220,185,55],[225,135,60],[200,80,65],[160,50,75],[100,30,65],[55,20,55],[20,15,48],[5,12,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0, pal.length-2), f=idx-i;
  const lum=0.85+Math.sin(rd*Math.PI)*0.15;
  const edge=Math.abs(rd)>0.85?1.25:(Math.abs(rd)>0.65?1.12:1.0);
  const glow=Math.max(0,rd)*0.1;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*80)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*20)|0)
  ];
}
